struct Bench {
    const char* name;
    int instrs_per_iter;
    void (*fn)(long long*);
};

int main() {
    long long *d_out, h_out[2];
    cudaMalloc(&d_out, LDG_BUF_SIZE + 4096);
    cudaMemset(d_out, 0, LDG_BUF_SIZE + 4096);

    Bench benches[] = {
    {"FADD tput ilp=1", 1, tput_FADD_ilp1},
    {"FADD tput ilp=2", 2, tput_FADD_ilp2},
    {"FADD tput ilp=4", 4, tput_FADD_ilp4},
